const item = { ...$json };
const src = (item.text ?? '').trim();

const escaped = src
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&apos;');

const withBreaks = escaped
  .replace(/、/g, '、<break time="120ms"/>')
  .replace(/。/g, '。<break time="220ms"/>')
  .replace(/！/g, '！<break time="220ms"/>')
  .replace(/？/g, '？<break time="220ms"/>')
  .replace(/!/g, '!<break time="220ms"/>')
  .replace(/\?/g, '?<break time="220ms"/>');

item.ssml = `<speak><prosody rate="95%" pitch="+0.5st">${withBreaks}</prosody></speak>`;

return [{ json: item }];
